/* Local application workspace. Essays are never sent to an external model. */
function advisingCheckpoints(){const rows=state.advisingDates||[];return `<section class="degree-checkpoint"><span class="eyebrow">APPLICATION & GRADUATION CHECKPOINTS</span><h3>Know when the next door opens.</h3>${advisingReadiness()}<p>Major admission, college transfer and graduation applications can be separate. Coursework completion alone does not submit an application or award a degree.</p>${rows.map(d=>`<p><strong>${esc(d.label)}</strong> · ${esc(d.date)} · ${esc(d.institution)} · ${esc(d.cycle)} · ${esc(d.track)}<br><small>Entered by you; confirm current applicability.</small> <a class="journey-secondary" href="${esc(ProductCore.safeURL(d.source))}" target="_blank" rel="noopener">Source ↗</a></p>`).join('')||'<p>No dated checkpoints confirmed for this student yet.</p>'}<a class="journey-secondary" href="#application-review">GPA, application preparation & dates →</a></section>`}
function advisingReadiness(){const goals=state.degreeGoals||[];if(!goals.length)return '<p>Add a program checklist to track preparation for major admission.</p>';const result=degreeOptimize();return goals.map(g=>{const reqs=g.requirements.filter(r=>r.phase==='admission'),done=reqs.filter(r=>{const a=(result.assignments||[]).filter(a=>a.goalId===g.id&&a.requirementId===r.id);return a.length>=(r.count||1)&&a.every(x=>x.completed)&&(!r.minCredits||a.reduce((sum,x)=>sum+(result.usage?.find(c=>c.key===x.course)?.credits||0),0)>=r.minCredits)});return `<p><strong>${esc(g.name)}</strong>: ${reqs.length?done.length+' / '+reqs.length+' entered admission categories complete':'Admission prerequisites not entered'}. Eligibility, application timing and graduation audit require college confirmation.</p>`}).join('')}
function advisingPage(){const a=state.advising||{},stats=AdvisingCore.gpas(state.courses||[],state.excludedAttempts||[]),goals=state.degreeGoals||[];return journeyPage(3,'Essay & Application Review (Beta)',`<p class="journey-lede">A separate preparation workspace, connected to your saved coursework. Honest feedback and clear next steps. Review the evidence behind suggestions and keep your own judgment. AI feedback is fallible; checklist completion is your own review, not institutional certification.</p><section class="degree-optimizer"><h2>Your record-based GPA</h2>${stats.groups.map((g,i)=>`<article class="degree-goal"><span class="eyebrow">${esc(g.institution)} · ${esc(g.units)} credits</span><h3>${g.gpa.toFixed(2)} estimated GPA</h3><p>${g.credits} graded attempted credits · ${g.attempts} observed attempts</p></article>`).join('')||'<p>Add completed graded courses with explicit credit units to calculate an estimate.</p>'}<p class="quiet-note">Credit-weighted 0–4 scale, by institution and credit system. Includes observed failing attempts; excludes withdrawals, pass/fail credit, transfer-credit rows and grades/units it cannot interpret. Numeric grades stay numeric; letter conversions use a standard A=4, B=3, C=2, D=1 scale with plus/minus adjustments. This is not an official cumulative or admissions GPA: missing attempts and institutional repeat/transfer rules can change it. ${stats.omitted} record(s) excluded. <a href="#history">Review coursework →</a></p><details><summary>What grade would help me reach my GPA goal?</summary><form id="gpa-target"><label>Record group<select name="group">${stats.groups.map((g,i)=>`<option value="${i}">${esc(g.institution)} · ${esc(g.units)}</option>`).join('')}</select></label><label>Your desired cumulative GPA<input name="target" type="number" min="0" max="4" step="0.01" value="3.5" required></label><label>Additional graded credits in the same system<input name="credits" type="number" min="0.5" max="100" step="0.5" value="5" required></label><button class="btn">Calculate grade scenarios</button></form><div id="gpa-scenarios" aria-live="polite"></div><p>Arithmetic scenarios, not admission simulations. A GPA target is a personal planning goal, not a claimed competitive cutoff.</p></details></section><section class="degree-optimizer">${admissionsEstimatorPanel()}<details><summary>Add a published admission GPA benchmark</summary><form id="advising-benchmark" class="form-grid"><label>College and major<input name="program" required maxlength="150"></label><label>Published average admitted GPA<input name="average" type="number" min="0" max="4" step="0.01" required></label><label>Cohort, year and applicant type<input name="cohort" required maxlength="150" placeholder="e.g. 2026 admitted transfer students"></label><label>GPA definition<input name="definition" required maxlength="150" placeholder="e.g. prerequisite GPA, cumulative GPA"></label><label>Official source URL<input name="source" type="url" required></label><button class="btn">Save sourced benchmark</button></form><p>Only enter a figure actually published for that population. An average is not a minimum or personal chance.</p></details>${(state.advisingBenchmarks||[]).map((b,i)=>`<article class="degree-goal"><h3>${esc(b.program)}: ${Number(b.average).toFixed(2)} published average entered by you</h3><p>${esc(b.cohort)} · ${esc(b.definition)}</p><a href="${esc(ProductCore.safeURL(b.source))}" target="_blank" rel="noopener">Entered source ↗</a><p>Not independently verified. Match the GPA definition and applicant cohort before comparing it with your own record.</p><button class="journey-secondary" data-remove-benchmark="${i}">Remove benchmark</button></article>`).join('')}<h3>Evidence to check before applying</h3><ul><li>Complete the published prerequisites and minimum grades for your applicant type.</li><li>Check whether college admission and admission to your major require different applications.</li><li>Verify the prompt, recommendation requirements and deadline for your specific cycle.</li><li>Use actual outcomes and reflection in your activities and essay. Report achievements accurately.</li></ul><a class="journey-secondary" href="#degrees">Review program checklists →</a></section><section class="degree-optimizer"><h2>Important dates</h2>${advisingCheckpoints()}<details><summary>Add a sourced deadline or checkpoint</summary><form id="advising-date" class="form-grid"><label>Checkpoint<select name="label">${options(['Apply to major','Apply to college / transfer','Apply for graduation','Register for classes','Financial aid / scholarship','Meet advisor'])}</select></label><label>Date<input name="date" type="date" required></label><label>College / program<input name="institution" maxlength="150" required></label><label>Applicable cycle<input name="cycle" required maxlength="80" placeholder="Autumn 2027 entry"></label><label>Applicant type<input name="track" required maxlength="100" placeholder="Current UW Seattle undergraduate"></label><label>Official source URL<input name="source" type="url" required></label><button class="btn">Add checkpoint</button></form><p>Check time zone and closing time on the official page. Saved dates are student-entered reminders, not live university notifications.</p></details>${(state.advisingDates||[]).map((d,i)=>`<button class="journey-secondary" data-remove-advising-date="${i}">Remove ${esc(d.label)} · ${esc(d.date)}</button>`).join('')}<details><summary>UW Seattle Informatics — sourced application guidance</summary><p>Current UW Seattle undergraduate applicants: the official page lists April 5 for autumn entry and October 5 for winter entry; weekend deadlines move to the following Monday at 5 p.m. Complete all four prerequisites by the end of the preceding quarter. Verify the cycle and deadline on the source before applying.</p><p>These rules are for current Seattle students. Transfer and first-year applicants have different routes; Bothell and Tacoma students should use transfer guidance. Transfer applicants do not need INFO 200 before applying, according to the prerequisites page.</p><a class="journey-secondary" href="https://ischool.uw.edu/programs/informatics/admissions/current-students" target="_blank" rel="noopener">Official current-student application rules ↗</a><a class="journey-secondary" href="https://ischool.uw.edu/programs/informatics/admissions/prerequisites" target="_blank" rel="noopener">Official prerequisites ↗</a><p class="quiet-note">Source snapshot checked November 9, 2026; not live-synced.</p></details></section><section class="degree-optimizer"><h2>Your statement & activities</h2><p>Private local writing checks, separate from course scheduling. This tool checks structure and your entered word limit; it does not judge admissions quality, verify accomplishments or predict acceptance. Text is kept in this page’s memory unless you explicitly save it to this device.</p><form id="essay-review"><label>Exact application prompt<textarea name="prompt" maxlength="6000">${esc(a.prompt||'')}</textarea></label><label>Published word limit (optional)<input name="limit" type="number" min="1" max="10000" value="${esc(a.limit||'')}"></label><label>Load a statement (.txt up to 100 KB, text PDF up to 5 MB / 10 pages)<input id="essay-file" type="file" accept=".txt,.pdf,text/plain,application/pdf"></label><label>Your draft<textarea id="essay-text" name="essay" maxlength="30000" rows="12">${esc(a.essay||'')}</textarea></label><label>Extracurriculars, work, care responsibilities or projects<textarea name="activities" maxlength="15000" rows="6" placeholder="For each: role, duration, what you did, outcome and what you learned.">${esc(a.activities||'')}</textarea></label><div class="actions"><button class="btn primary">Review writing checks</button><button class="btn" id="save-application-draft" type="button">Save draft to this device</button><button class="btn" id="clear-application-draft" type="button">Delete saved draft</button></div></form><div id="essay-feedback" aria-live="polite"></div><p class="quiet-note">No external AI service is connected. Saved essay text is excluded from Camino workspace sync and backup exports; only this browser stores it. Use a private device for personal statements.</p></section><details class="journey-advanced"><summary>Official college sources & transfer guides</summary><p>Official links are research starting points. No live university data connection, guaranteed equivalency coverage or automatic update job is configured.</p>${advisingResources()}</details>`,'roadmap')}
function advisingResources(){const aliases={'uws':'University of Washington Seattle','uwb':'University of Washington Bothell','uwt':'University of Washington Tacoma','wsu':'Washington State University','bellevue':'Bellevue College','cascadia':'Cascadia College','seattle-bachelors':'Seattle Colleges'};return ProgramCatalog.institutions.map(s=>`<article class="degree-goal"><h3>${esc(s.name)}</h3><a class="journey-secondary" href="${esc(s.url)}" target="_blank" rel="noopener">Official programs & college navigation ↗</a><a class="journey-secondary" href="${esc(ProductCore.institutions.find(i=>i.name===aliases[s.id])?.admissions||s.url)}" target="_blank" rel="noopener">Official admissions navigation ↗</a></article>`).join('')+`<p><a class="journey-secondary" href="https://admit.washington.edu/apply/transfer/equivalency-guide/" target="_blank" rel="noopener">UW Seattle community college equivalency guides ↗</a></p><p><a class="journey-secondary" href="https://www.uwb.edu/registrar/policies/community-college-course-equivalency-guide" target="_blank" rel="noopener">UW Bothell equivalency guides ↗</a></p><p><a class="journey-secondary" href="https://www.sbctc.edu/colleges-staff/programs-services/transfer/direct-transfer-agreement.aspx" target="_blank" rel="noopener">Washington direct transfer agreement ↗</a></p>`}
function bindAdvising(){bindAdmissionsEstimator();const form=document.querySelector('#essay-review');if(form){try{const saved=JSON.parse(localStorage.getItem('camino-application-draft')||'null');if(saved)for(const k of ['essay','prompt','limit','activities','applicationContext','requirements'])if(form.elements.namedItem(k))form.elements.namedItem(k).value=String(saved[k]||'')}catch{}form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form)),r=AdvisingCore.writing(f.essay,f.prompt,f.limit);document.querySelector('#essay-feedback').innerHTML=`<h3>What you have already done</h3><ul>${r.strengths.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Start with a short example from your own experience.</li>'}</ul><h3>Next revisions</h3><ul>${r.improve.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Activity review checklist</h3><p>${f.activities.trim()?'You have recorded activities or responsibilities. For each entry, review the role, duration, your contribution, an honest outcome and reflection.':'Add activities, work, personal projects or care responsibilities you want reviewers to understand.'}</p><p>These checks cannot determine whether the essay answers the prompt, identify admissions weaknesses or estimate changes in acceptance probability. Ask a counselor or qualified reviewer for substantive feedback.</p>`};document.querySelector('#save-application-draft').onclick=()=>{const f=Object.fromEntries(new FormData(form));delete f.file;try{localStorage.setItem('camino-application-draft',JSON.stringify({essay:f.essay,prompt:f.prompt,limit:f.limit,activities:f.activities,applicationContext:f.applicationContext,requirements:f.requirements}));toast('Draft saved only in this browser.')}catch{toast('Could not save this draft. Your text is still on this page; copy it before leaving or free browser storage.')}};document.querySelector('#clear-application-draft').onclick=()=>{localStorage.removeItem('camino-application-draft');form.reset();for(const k of ['essay','prompt','activities','applicationContext','requirements'])if(form.elements.namedItem(k))form.elements.namedItem(k).value='';document.querySelector('#essay-feedback').textContent='';toast('Saved application draft deleted.')};document.querySelector('#essay-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;let text='';try{if(/\.pdf$/i.test(f.name)){if(f.size>5*1024*1024)return toast('PDF must be under 5 MB.');const bytes=new Uint8Array(await f.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')return toast('That file is not a PDF.');await loadDocLibraries();const pdf=await pdfjsLib.getDocument({data:bytes,isEvalSupported:false,standardFontDataUrl:new URL('vendor/standard_fonts/',document.baseURI).href}).promise;try{if(pdf.numPages>10)return toast('Use a statement PDF of up to 10 pages.');for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);text+=TranscriptImport.pdfText((await page.getTextContent()).items)+'\n\n';if(text.length>30000)break;}}finally{await pdf.destroy()}if(!text.trim())return toast('This PDF has no extractable text. Paste your statement or use a text-based PDF.');}else{if(!/\.txt$/i.test(f.name)||f.size>100*1024)return toast('Choose a .txt up to 100 KB or a text PDF up to 5 MB.');text=await f.text();}if(text.length>30000||/[\u0000-\u0008\u000e-\u001f]/.test(text))return toast('Use a plain-text draft of up to 30,000 characters.');if(!form.isConnected||e.target.files?.[0]!==f)return;document.querySelector('#essay-text').value=text;toast('Draft loaded locally; review the writing when ready.')}catch{toast('Could not read that text file.')}}}
 document.querySelector('#gpa-target')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),g=AdvisingCore.gpas(state.courses||[],state.excludedAttempts||[]).groups[+f.group],r=AdvisingCore.targetGrade(g,f.target,f.credits);if(!r)return toast('Add a graded record and valid GPA target first.');document.querySelector('#gpa-scenarios').innerHTML=`<h3>${r.possible?'Needed average on the additional credits: '+r.minimum.toFixed(2):'This target cannot be reached with these credits on a 4.0 scale.'}</h3><p>Holding existing attempts fixed and without repeat forgiveness.</p><div class="table-wrap"><table><thead><tr><th>Future average grade</th><th>Resulting estimated GPA</th></tr></thead><tbody>${r.scenarios.map(s=>`<tr><td>${s.grade.toFixed(1)}</td><td>${s.gpa.toFixed(3)}</td></tr>`).join('')}</tbody></table></div>`});
 document.querySelector('#advising-benchmark')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!ProductCore.safeURL(f.source)||!Number.isFinite(+f.average)||+f.average<0||+f.average>4)return toast('Enter a 0–4 average and HTTPS official source.');state.advisingBenchmarks||=[];if(state.advisingBenchmarks.length>=20)return toast('Use up to 20 sourced benchmarks.');state.advisingBenchmarks.push(f);save();render()});document.querySelectorAll('[data-remove-benchmark]').forEach(b=>b.onclick=()=>{state.advisingBenchmarks.splice(+b.dataset.removeBenchmark,1);save();render()});
 document.querySelector('#advising-date')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!ProductCore.safeURL(f.source))return toast('Use an HTTPS official source.');state.advisingDates||=[];if(state.advisingDates.length>=40)return toast('Use up to 40 dated checkpoints.');state.advisingDates.push(f);state.advisingDates.sort((a,b)=>a.date.localeCompare(b.date));save();render()});document.querySelectorAll('[data-remove-advising-date]').forEach(b=>b.onclick=()=>{state.advisingDates.splice(+b.dataset.removeAdvisingDate,1);save();render()})}
function installAdvising(){const oldBind=bind;bind=function(){oldBind();bindAdvising()};const oldRoadmap=roadmap;roadmap=function(){return oldRoadmap()+advisingCheckpoints()};const oldApplications=applications;applications=function(){return advisingPage()+`<details class="journey-advanced"><summary>Earlier application tasks</summary>${oldApplications()}</details>`}}
